package main

const jsCheckins = `
let accountCheckins={accounts:[]},checkinRevision=0,providerQuick="all",checkinFlight=null,checkinLoading=false,checkinLoadError="",checkinLastAttempt=0,checkinNeedsRefresh=false;
const checkinSaving=new Set();
function checkinToday(timezone=settings.timezone||"Asia/Taipei"){try{const parts=new Intl.DateTimeFormat("en-US",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date()),get=type=>parts.find(p=>p.type===type).value;return get("year")+"-"+get("month")+"-"+get("day");}catch{return "";}}
function checkinSnapshotCurrent(value=accountCheckins){return value.timezone===(settings.timezone||"Asia/Taipei")&&value.date===checkinToday()&&Array.isArray(value.accounts);}
function pendingCheckins(provider){return checkinSnapshotCurrent()?accountCheckins.accounts.filter(a=>a.provider_id===provider&&a.required&&!a.completed_at):[];}
function providerCheckinPending(p){return p.config?.requires_daily_checkin&&(!checkinSnapshotCurrent()||pendingCheckins(p.id).length>0);}
function renderCheckinSummary(){
 const box=$("checkin-summary");if(!box)return;const required=providers.some(p=>p.config?.requires_daily_checkin);box.hidden=!required;box.replaceChildren();
 if(required){const current=checkinSnapshotCurrent(),rows=current?accountCheckins.accounts.filter(a=>a.required):[],done=rows.filter(a=>a.completed_at).length,heading=el("div",undefined,"checkin-summary-heading");heading.append(el("strong",current?"今日簽到 · "+done+" / "+rows.length+" 已記錄":"今日簽到 · 待更新"));box.append(heading);if(current)box.append(el("small",accountCheckins.date+" · "+accountCheckins.timezone,"source-line"));const tools=el("div",undefined,"actions");box.append(tools);action(tools,"查看待簽到",()=>{providerQuick="pending";document.querySelectorAll("[data-provider-quick]").forEach(n=>n.setAttribute("aria-pressed",String(n.dataset.providerQuick==="pending")));renderProviders();});const retry=action(tools,"更新簽到狀態",refreshAccountCheckins);retry.disabled=checkinLoading;if(checkinLoadError)detailState(box,(current?"保留最近一次狀態。":"今日狀態尚未確認。")+checkinLoadError,true);else if(checkinLoading)box.append(el("small","正在更新簽到狀態…","source-line"));}
 if($("detail").open&&$("detail").dataset.kind==="provider")$("detail-content").providerCheckinsRender?.();
}
async function refreshAccountCheckins(){
 const timezone=settings.timezone||"Asia/Taipei";if(checkinFlight?.timezone===timezone)return checkinFlight.promise;const revision=++checkinRevision,flight={timezone,promise:null};checkinFlight=flight;checkinLoading=true;checkinLoadError="";checkinLastAttempt=Date.now();checkinNeedsRefresh=false;renderCheckinSummary();
 flight.promise=(async()=>{try{const value=await api("/checkins/accounts?timezone="+encodeURIComponent(timezone));if(revision!==checkinRevision||timezone!==(settings.timezone||"Asia/Taipei"))return;if(!checkinSnapshotCurrent(value))throw Error("日期或時區已變更，請重新讀取。");accountCheckins=value;}catch(error){if(revision===checkinRevision)checkinLoadError=error.message;}finally{if(revision===checkinRevision){checkinFlight=null;checkinLoading=false;renderProviders();}}})();return flight.promise;
}
function providerCheckins(parent,p,ticket){
 if(!p.config.requires_daily_checkin)return;const box=detailSection(parent,"每日簽到","先到站點完成簽到，再逐帳戶記錄。此按鈕只保存你的完成紀錄。"),status=el("div"),list=el("div",undefined,"cards");box.append(status,list);
 const render=()=>{if(!detailCurrent(ticket))return;const active=document.activeElement,focusedAccount=list.contains(active)?active.closest('[data-checkin-account]')?.dataset.checkinAccount:null,focusedKind=active?.matches('button')?'button':active?.matches('a')?'a':'';status.replaceChildren();list.replaceChildren();if(!checkinSnapshotCurrent()){detailState(status,checkinLoading?"正在讀取今日簽到…":"今日狀態尚未確認。"+(checkinLoadError||"請更新簽到狀態。"),!!checkinLoadError,checkinLoading?null:refreshAccountCheckins);if(focusedAccount!=null){status.tabIndex=-1;status.focus({preventScroll:true});}return;}
  const value=accountCheckins;status.append(el("p",value.date+" · "+value.timezone,"detail-provenance"));if(checkinLoadError)detailState(status,"保留最近一次狀態。"+checkinLoadError,true,refreshAccountCheckins);const rows=value.accounts.filter(a=>a.provider_id===p.id&&a.required);if(!rows.length)list.append(el("p","先新增帳戶，再記錄簽到。","section-description"));
  for(const a of rows){const card=item(list,a.label||a.account_id,a.completed_at?"今日已記錄 · "+new Date(a.completed_at).toLocaleTimeString():"今天尚未記錄");card.dataset.checkinAccount=a.account_id;if(a.checkin_url){const link=el("a","前往站點簽到","link-button");link.href=a.checkin_url;link.target="_blank";link.rel="noopener noreferrer";link.addEventListener("click",()=>checkinNeedsRefresh=true);card.append(link);}
   if(!a.completed_at){const id=JSON.stringify([p.id,a.account_id]),button=providerAction(card,"我已完成這個帳戶的簽到",ticket,async commit=>{if(!checkinSnapshotCurrent(value)){await refreshAccountCheckins();throw Error("日期或時區已變更，請確認今天的簽到後再記錄。");}if(checkinSaving.has(id))return "正在保存完成紀錄";checkinSaving.add(id);try{const receipt=await commit("/checkins/accounts",{provider_id:p.id,account_id:a.account_id,timezone:value.timezone,date:value.date});checkinRevision++;checkinFlight=null;checkinLoading=false;if(checkinSnapshotCurrent(value)&&receipt.date===value.date&&receipt.provider_id===p.id&&receipt.account_id===a.account_id){const base=checkinSnapshotCurrent()?accountCheckins:value;accountCheckins={...base,accounts:base.accounts.map(row=>row.provider_id===p.id&&row.account_id===a.account_id?{...row,completed_at:receipt.completed_at,source:receipt.source}:row)};}renderProviders();await refreshAccountCheckins();return "已保存這個帳戶的完成紀錄";}finally{checkinSaving.delete(id);renderCheckinSummary();}});button.disabled=checkinSaving.has(id);}
  }
  if(focusedAccount!=null){const card=[...list.querySelectorAll('[data-checkin-account]')].find(n=>n.dataset.checkinAccount===focusedAccount),target=focusedKind&&card?.querySelector(focusedKind);if(target&&!target.disabled)target.focus({preventScroll:true});else if(card){card.tabIndex=-1;card.focus({preventScroll:true});}else{status.tabIndex=-1;status.focus({preventScroll:true});}}
 };$("detail-content").providerCheckinsRender=render;render();refreshAccountCheckins();return refreshAccountCheckins;
}
function revalidateCheckins(){if(document.hidden||!providers.some(p=>p.config?.requires_daily_checkin)||checkinLoading)return;if(checkinNeedsRefresh||!checkinSnapshotCurrent()||Date.now()-checkinLastAttempt>=60000){renderProviders();refreshAccountCheckins();}}
function bindProviderQuickFilters(){document.querySelectorAll("[data-provider-quick]").forEach(b=>b.addEventListener("click",()=>{providerQuick=b.dataset.providerQuick;document.querySelectorAll("[data-provider-quick]").forEach(n=>n.setAttribute("aria-pressed",String(n===b)));renderProviders();if(providerQuick==="pending"&&!checkinSnapshotCurrent())refreshAccountCheckins();}));window.addEventListener("focus",revalidateCheckins);document.addEventListener("visibilitychange",()=>{if(!document.hidden)revalidateCheckins();});setInterval(()=>{if(!document.hidden&&!checkinSnapshotCurrent()&&Date.now()-checkinLastAttempt>=60000)revalidateCheckins();},60000);}
`
